CREATE TRIGGER protect_billable_usage_owner BEFORE UPDATE ON billable_usage FOR EACH ROW BEGIN IF NOT (NEW.id<=>OLD.id) OR NOT (NEW.created_at<=>OLD.created_at) OR NOT (NEW.tenant_id<=>OLD.tenant_id) OR NOT (NEW.subscription_id<=>OLD.subscription_id) OR NOT (NEW.branch_id<=>OLD.branch_id) OR NOT (NEW.short_link_id<=>OLD.short_link_id) OR NOT (NEW.metric<=>OLD.metric) OR NOT (NEW.request_key<=>OLD.request_key) OR NOT (NEW.form_digest<=>OLD.form_digest) OR NOT (NEW.input_sha256<=>OLD.input_sha256) OR NOT (NEW.language<=>OLD.language) OR NOT (NEW.reserved_tokens<=>OLD.reserved_tokens) OR NOT (NEW.expires_at<=>OLD.expires_at) OR OLD.status<>'reserved' OR NEW.status='reserved' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Immutable metering ownership or completed result'; END IF; END
